(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-380":{scenario:{company:"Cloud Hill Tea Co.",supervisor:{name:"Quách Tùng Lâm",role:{vi:"Giám đốc Marketing",en:"Marketing Director"}},ref_code:"BRF-1185",title:{vi:"Claim có bằng chứng. Độ phủ không vượt 100%.",en:"Claims with evidence. Reach never tops 100%."},brief:{vi:"Bạn duyệt hồ sơ ra mắt BRF-1185 của dòng trà đóng chai ít ngọt. Kết quả kiểm nghiệm: 4,5 g đường/100 ml, công thức gốc 7,0 g/100 ml; bản nháp nhãn ghi claim SUGAR-FREE (“Không đường”). Đợt TVC 1 đạt 312 GRP trên nhóm mục tiêu với tần suất trung bình 4,0 lần, nhưng báo cáo nháp ghi độ phủ 312%. Sửa claim theo hướng dẫn claim nội bộ (ngưỡng mô phỏng) và độ phủ 1+ (%), rồi lập báo cáo có căn cứ.",en:"You are approving launch file BRF-1185 for a less-sweet bottled tea line. Lab result: 4.5 g sugar/100 ml, original recipe 7.0 g/100 ml; the draft label carries the claim SUGAR-FREE. TVC flight 1 delivered 312 GRPs on the target audience at an average frequency of 4.0, yet the draft report shows 312% reach. Correct the claim per the internal claim guideline (training thresholds) and the 1+ reach (%), then write an evidence-based report."},reference_title:{vi:"Hướng dẫn claim & báo cáo hậu kiểm truyền thông đã duyệt · BRF-1185",en:"Approved claim guideline & media post-buy · BRF-1185"},fields:[{id:"CLAIM",label:{vi:"Claim đường trên nhãn",en:"Sugar claim on label"},initial:"SUGAR-FREE",expected:"REDUCED-SUGAR",choices:["SUGAR-FREE","LOW-SUGAR","REDUCED-SUGAR"],reference:"Hướng dẫn claim dinh dưỡng nội bộ",hint:{vi:"Ngưỡng mô phỏng: không đường ≤ 0,5 g/100 ml; ít đường ≤ 2,5 g/100 ml; giảm đường khi thấp hơn công thức gốc ít nhất 30%.",en:"Training thresholds: sugar-free <= 0.5 g/100 ml; low sugar <= 2.5 g/100 ml; reduced sugar if at least 30% below the original recipe."}},{id:"REACH_PCT",label:{vi:"Độ phủ 1+ đợt TVC 1 (%)",en:"TVC flight 1 reach 1+ (%)"},initial:"312",expected:"78",reference:"Báo cáo hậu kiểm truyền thông",ref_value:{vi:"Tổng 312 GRP trên nhóm mục tiêu; tần suất trung bình 4,0",en:"Total 312 GRPs on the target audience; average frequency 4.0"},hint:{vi:"GRP là tổng số lần tiếp cận tính theo phần trăm, không phải độ phủ; độ phủ không thể vượt 100%.",en:"GRPs are total exposures in percentage points, not reach; reach can never exceed 100%."}}],sop32:{vi:"GRP = độ phủ (%) x tần suất trung bình, nên độ phủ 1+ (%) = GRP / tần suất trung bình. Không báo cáo GRP như độ phủ; claim phải có kết quả kiểm nghiệm làm bằng chứng.",en:"GRP = reach (%) x average frequency, so reach 1+ (%) = GRP / average frequency. Never report GRPs as reach; every claim needs lab results as evidence."},context:{label:"BRAND LAUNCH FILE / BRF-1185",metrics:[{label:{vi:"Đường / 100 ml",en:"Sugar / 100 ml"},value:"4.5 g (gốc / original 7.0 g)"},{label:{vi:"Tổng GRP đợt 1",en:"Flight 1 GRPs"},value:"312"},{label:{vi:"Tần suất trung bình",en:"Average frequency"},value:"4.0"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Cứ in ‘Không đường’ và thêm ‘tốt cho người tiểu đường’, đối thủ cũng ghi vậy. File in bao bì phải chốt tối nay, sửa là lỡ lịch lên kệ.”",en:"The sales director messages you: “Just print sugar-free and add good for diabetics, competitors say the same. The packaging file must be locked tonight or we miss the shelf date.”"},options:{safe:{vi:"Từ chối claim sai và claim sức khỏe chưa được phép, báo Giám đốc Marketing cùng bộ phận chất lượng, pháp chế; dùng claim “giảm hơn 35% đường so với công thức gốc” kèm kết quả kiểm nghiệm.",en:"Refuse the false claim and the unauthorized health claim, inform the Marketing Director, QA and Legal; use the claim 35% less sugar than the original recipe, backed by lab results."},shortcut:{vi:"In “Không đường” cho lô đầu cho kịp lên kệ, lô sau sẽ sửa nhãn.",en:"Print sugar-free on the first batch to make the shelf date and fix the label later."},wait:{vi:"Không chốt file và chờ kinh doanh với nhà in tự quyết nội dung nhãn.",en:"Do not lock the file and wait for Sales and the printer to decide the label."}},questions:{vi:["Vì sao claim đúng là REDUCED-SUGAR mà không phải SUGAR-FREE hay LOW-SUGAR? Hãy dẫn số liệu kiểm nghiệm và ngưỡng.","Trình bày cách tính độ phủ 78% và rủi ro thương hiệu, pháp lý nếu in claim sai hoặc báo cáo GRP như độ phủ."],en:["Why is REDUCED-SUGAR right rather than SUGAR-FREE or LOW-SUGAR? Cite the lab data and thresholds.","Explain how you reached 78% reach and the brand and legal risks of a false claim or reporting GRPs as reach."]},hints:{vi:["So kết quả kiểm nghiệm với từng ngưỡng claim, rồi tính mức giảm so với công thức gốc.","Theo SOP mục 3.2, chia tổng GRP cho tần suất trung bình để có độ phủ.","Đọc SOP mục 4.2: mọi claim dinh dưỡng, sức khỏe phải có bằng chứng và được pháp chế duyệt trước khi in."],en:["Compare the lab result with each claim threshold, then compute the reduction versus the original recipe.","Per SOP 3.2, divide total GRPs by average frequency to get reach.","Read SOP 4.2: every nutrition or health claim needs evidence and Legal approval before printing."]}},learning:{summary:{vi:"Quản lý thương hiệu chịu trách nhiệm toàn diện về sức khỏe và tăng trưởng của một thương hiệu: định vị, chân dung khách hàng, danh mục sản phẩm, giá, bao bì, truyền thông và ngân sách marketing. Nghề đòi hỏi thấu hiểu người tiêu dùng, đọc số liệu thị trường và truyền thông, điều phối agency và các phòng ban, đồng thời bảo vệ niềm tin bằng các claim trung thực, có bằng chứng.",en:"A Brand Manager owns the health and growth of a brand end to end: positioning, target consumer, portfolio, pricing, packaging, communication and marketing budget. The role requires consumer insight, reading market and media data, steering agencies and internal teams, and protecting trust through honest, evidence-based claims."},responsibilities:{vi:["Xây dựng và giữ nhất quán định vị, tính cách và cấu trúc thương hiệu.","Lập kế hoạch thương hiệu năm: mục tiêu, ngân sách, kế hoạch ra mắt và truyền thông.","Viết brief cho agency sáng tạo, truyền thông và duyệt sản phẩm sáng tạo theo chiến lược.","Theo dõi sức khỏe thương hiệu: nhận biết, cân nhắc, dùng thử, mua lặp lại, thị phần.","Phối hợp R&D, chất lượng, pháp chế để bao bì, claim và quảng cáo đúng quy định."],en:["Build and keep brand positioning, personality and architecture consistent.","Write the annual brand plan: goals, budget, launches and communication.","Brief creative and media agencies and approve creative work against strategy.","Track brand health: awareness, consideration, trial, repeat and market share.","Work with R&D, QA and Legal so packaging, claims and ads comply with regulations."]},competencies:[{name:{vi:"Chiến lược thương hiệu",en:"Brand strategy"},desc:{vi:"Xác định khách hàng mục tiêu, sự thật ngầm hiểu, lợi ích khác biệt và lý do tin tưởng.",en:"Define the target, consumer insight, differentiated benefit and reasons to believe."}},{name:{vi:"Đọc số liệu thị trường",en:"Market data literacy"},desc:{vi:"Phân tích thị phần, phân phối, giá, chỉ số sức khỏe thương hiệu và hậu kiểm truyền thông.",en:"Analyze share, distribution, price, brand health and media post-buy data."}},{name:{vi:"Quản trị sáng tạo",en:"Creative leadership"},desc:{vi:"Viết brief sắc, phản hồi sáng tạo dựa trên chiến lược thay vì sở thích cá nhân.",en:"Write sharp briefs and give creative feedback based on strategy, not taste."}},{name:{vi:"Quản lý ngân sách & P&L",en:"Budget & P&L management"},desc:{vi:"Phân bổ ngân sách theo hiệu quả, theo dõi biên lợi nhuận và đóng góp của thương hiệu.",en:"Allocate budget by effectiveness and track the brand's margin and contribution."}},{name:{vi:"Liêm chính thương hiệu",en:"Brand integrity"},desc:{vi:"Chỉ dùng claim có bằng chứng, từ chối thông điệp gây hiểu lầm dù chịu áp lực doanh số.",en:"Use only substantiated claims and refuse misleading messages despite sales pressure."}}],knowledge:{vi:["Mô hình tài sản thương hiệu dựa trên khách hàng (CBBE) của Keller và tuyên bố định vị.","Phễu thương hiệu: nhận biết, cân nhắc, dùng thử, mua lặp lại, trung thành.","Chỉ số truyền thông: GRP, TRP, độ phủ, tần suất, CPP, thị phần tiếng nói (SOV).","Luật Quảng cáo số 16/2012/QH13 và các văn bản sửa đổi, hướng dẫn.","Nghị định 43/2017/NĐ-CP về nhãn hàng hóa (sửa đổi bởi Nghị định 111/2021/NĐ-CP).","Hướng dẫn Codex CAC/GL 23-1997 về sử dụng claim dinh dưỡng và sức khỏe."],en:["Keller's customer-based brand equity (CBBE) model and the positioning statement.","The brand funnel: awareness, consideration, trial, repeat, loyalty.","Media metrics: GRP, TRP, reach, frequency, CPP and share of voice (SOV).","Advertising Law No. 16/2012/QH13 with its amendments and guidance.","Decree 43/2017/ND-CP on goods labeling (amended by Decree 111/2021/ND-CP).","Codex guideline CAC/GL 23-1997 on the use of nutrition and health claims."]},tools:["Dữ liệu bán lẻ (retail audit)","Khảo sát sức khỏe thương hiệu (brand tracking)","Công cụ lập kế hoạch & hậu kiểm truyền thông","Social listening","Microsoft Excel / PowerPoint","Power BI"],kpis:{vi:["Thị phần theo giá trị và sản lượng so với kế hoạch.","Chỉ số nhận biết, cân nhắc và tỷ lệ dùng thử, mua lặp lại.","Hiệu quả truyền thông: độ phủ hiệu quả, CPP, SOV so với thị phần.","Số claim, bao bì bị khiếu nại hoặc phải thu hồi (mục tiêu bằng 0)."],en:["Value and volume market share versus plan.","Awareness, consideration, trial and repeat rates.","Media effectiveness: effective reach, CPP and SOV versus share.","Claims or packaging complaints and recalls (target zero)."]},day:[{time:"08:30",vi:"Xem số bán hàng tuần, thị phần và phân phối theo kênh của thương hiệu.",en:"Review weekly sales, share and distribution by channel."},{time:"10:00",vi:"Họp agency sáng tạo duyệt kịch bản TVC theo brief và định vị.",en:"Meet the creative agency to approve the TVC script against the brief and positioning."},{time:"13:30",vi:"Làm việc với R&D, chất lượng, pháp chế về claim và bản thiết kế bao bì mới.",en:"Work with R&D, QA and Legal on claims and the new packaging artwork."},{time:"15:30",vi:"Đọc báo cáo hậu kiểm truyền thông: GRP, độ phủ, tần suất, chi phí.",en:"Read the media post-buy: GRPs, reach, frequency and cost."},{time:"17:00",vi:"Cập nhật kế hoạch ra mắt, ngân sách và rủi ro cần báo Giám đốc Marketing.",en:"Update the launch plan, budget and risks for the Marketing Director."}],mistakes:{vi:["Báo cáo GRP như độ phủ, làm ban lãnh đạo hiểu sai số người thực sự xem quảng cáo.","In claim dinh dưỡng vượt bằng chứng kiểm nghiệm vì đối thủ cũng làm vậy.","Thay đổi định vị, nhận diện liên tục theo từng chiến dịch, làm loãng tài sản thương hiệu."],en:["Reporting GRPs as reach, misleading leaders about how many people saw the ad.","Printing nutrition claims beyond lab evidence because competitors do so.","Changing positioning and identity with every campaign, diluting brand equity."]},career:[{vi:"Trợ lý thương hiệu",en:"Assistant Brand Manager"},{vi:"Quản lý thương hiệu",en:"Brand Manager"},{vi:"Quản lý ngành hàng / Quản lý thương hiệu cấp cao",en:"Category Manager / Senior Brand Manager"},{vi:"Giám đốc Marketing",en:"Marketing Director"}],glossary:[{term:"GRP",vi:"Tổng điểm rating, bằng độ phủ (%) nhân tần suất trung bình trên một nhóm khán giả.",en:"Gross rating points, reach (%) times average frequency on an audience."},{term:"Reach 1+",vi:"Tỷ lệ khán giả mục tiêu thấy quảng cáo ít nhất một lần trong đợt phát sóng.",en:"Share of the target audience exposed to the ad at least once during the flight."},{term:"Positioning",vi:"Vị trí khác biệt thương hiệu muốn chiếm trong tâm trí khách hàng mục tiêu.",en:"The distinctive place a brand aims to hold in the target consumer's mind."},{term:"SOV",vi:"Thị phần tiếng nói, tỷ lệ chi tiêu hoặc hiện diện truyền thông của thương hiệu trong ngành hàng.",en:"Share of voice, the brand's share of media spend or presence in the category."},{term:"Claim",vi:"Tuyên bố về đặc tính, lợi ích sản phẩm trên nhãn hoặc quảng cáo, phải có bằng chứng.",en:"A statement about product attributes or benefits on pack or in ads that needs evidence."}],quiz:[{q:{vi:"Một đợt quảng cáo đạt 240 GRP với tần suất trung bình 3,0. Độ phủ 1+ là bao nhiêu?",en:"A flight delivers 240 GRPs at an average frequency of 3.0. What is reach 1+?"},options:{vi:["240%","720%","80%","60%"],en:["240%","720%","80%","60%"]},answer:2,explain:{vi:"Độ phủ = GRP / tần suất = 240 / 3,0 = 80%.",en:"Reach = GRP / frequency = 240 / 3.0 = 80%."}},{q:{vi:"Thành phần nào bắt buộc phải có trong một tuyên bố định vị tốt?",en:"Which element must a good positioning statement include?"},options:{vi:["Khách hàng mục tiêu, lợi ích khác biệt và lý do tin tưởng","Danh sách mọi tính năng sản phẩm","Giá bán lẻ đề xuất","Tên agency sáng tạo"],en:["Target, differentiated benefit and reason to believe","A list of every product feature","The suggested retail price","The creative agency's name"]},answer:0,explain:{vi:"Định vị trả lời: dành cho ai, khác biệt gì và vì sao nên tin.",en:"Positioning answers who it is for, what is different and why to believe it."}},{q:{vi:"Sản phẩm có 4,5 g đường/100 ml, công thức gốc 7,0 g. Theo ngưỡng mô phỏng trong bài, claim nào hợp lệ?",en:"A product has 4.5 g sugar/100 ml versus 7.0 g originally. Under the training thresholds, which claim is valid?"},options:{vi:["Không đường","Ít đường","Không có claim nào","Giảm đường so với công thức gốc"],en:["Sugar-free","Low sugar","No claim at all","Reduced sugar versus the original"]},answer:3,explain:{vi:"4,5 g vượt ngưỡng không đường và ít đường, nhưng thấp hơn công thức gốc khoảng 35,7% nên đủ điều kiện giảm đường.",en:"4.5 g exceeds the sugar-free and low-sugar thresholds but is about 35.7% below the original, so reduced sugar qualifies."}},{q:{vi:"Kinh doanh muốn in “tốt cho người tiểu đường” lên bao bì cho kịp lên kệ. Bạn làm gì?",en:"Sales wants good for diabetics printed on pack to make the shelf date. What do you do?"},options:{vi:["In lô đầu rồi sửa sau","Từ chối, báo pháp chế, chất lượng và dùng claim có bằng chứng","In chữ nhỏ ở mặt sau","Chỉ ghi trên mạng xã hội"],en:["Print the first batch and fix later","Refuse, inform Legal and QA and use an evidenced claim","Print it small on the back","Say it only on social media"]},answer:1,explain:{vi:"Claim sức khỏe chưa được chứng minh và cho phép là gây hiểu lầm, có thể bị xử phạt và thu hồi bao bì.",en:"Unproven, unauthorized health claims mislead consumers and can lead to penalties and packaging recalls."}}],tools_en:["Retail audit data","Brand health tracking surveys","Media planning & post-buy analysis tools","Social listening","Microsoft Excel / PowerPoint","Power BI"]}}})})(window.KKR);
